INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-08-05' FROM countries WHERE name_en = 'Uruguay';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'en', 'Pre-authorized numbered invoicing (CAE) with mandatory electronic transmission to DGI -- phased in by taxpayer revenue tier since 2012, and universal for VAT taxpayers since 1 January 2025', 'This deep-dive page reflects publicly available DGI guidance and industry reporting as of early August 2026 and is provided for general awareness, not legal or tax advice. Confirm current requirements directly with DGI or a Uruguayan tax adviser before relying on this page for compliance decisions.', 'Uruguay''s CFE regime began with Decreto 36/012 in 2012, phased in mandatory adoption by taxpayer revenue tier from 2014 to 2019, and closed its remaining exemption window on 1 January 2025, when essentially all VAT taxpayers became required electronic issuers. DGI continues to evolve the underlying technical schema, most recently with new mandatory validation controls in 2026.', 'A CFE is generated as a digitally signed XML document, using a numbered range (CAE) DGI has pre-authorized to the issuer, and transmitted to DGI for structural and format validation before being delivered to the recipient with a verification QR code. This is best understood as pre-authorized numbering with mandatory post-transmission validation -- DGI does not approve each individual invoice in real time before it reaches the buyer, but every CFE must still reach DGI and pass its checks to be a valid tax document.', 'The mandate has expanded in stages: a voluntary pilot and legal foundation (2012), a multi-year phased rollout by taxpayer revenue tier (2014-2019), and a final deadline (Resolución 2548/023) that closed the exemption window for essentially all remaining VAT taxpayers on 1 January 2025. A short, defined list of exemptions remains -- see the dedicated scope card below for exactly who''s still excluded.', 'Most businesses reading this are likely already required to issue CFE, given how long Uruguay''s mandate has been in place -- the real, current work is usually about maintaining compliance as DGI evolves the technical schema, not about a first-time rollout.', 'Uruguay sets no CFE-specific fine schedule -- Decreto 36/012 itself says non-compliance is punished under the general Código Tributario regime, not a dedicated e-invoicing penalty table. That means real exposure runs through ordinary tax-procedure provisions: formal non-compliance, understated-tax fines, and -- for genuine deceit -- criminal fraud liability.', 'Uruguay requires CFE (Comprobante Fiscal Electrónico) issuance via DGI-preauthorized numbered ranges, with mandatory electronic transmission and validation, for essentially all VAT taxpayers. In place in some form since 2012 and universal since 1 January 2025, it''s one of the most mature e-invoicing regimes in Latin America -- DGI reported the system already covered 98% of documentation issued nationwide by the time the exemption window closed.', '🇺🇾' FROM countries WHERE name_en = 'Uruguay';
