INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Uruguay';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & transmission', '[["Invoice format", "XML, digitally signed with an accredited electronic certificate"], ["Numbering/authorization", "CAE (Constancia de Autorización de Emisión) -- a pre-authorized block of sequential numbers, requested in batches of at least 100, valid two years"], ["Transmission", "Each CFE is sent to DGI for structural/format validation, then delivered to the recipient"], ["Confirmation", "DGI''s acceptance is asynchronous processing, not a final tax determination -- documents remain subject to later audit"]]', 'Uruguay''s CFE is best understood as pre-authorized numbering with mandatory post-transmission validation -- not a strict per-invoice clearance gate like Mexico''s CFDI, but not a simple after-the-fact report either.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Uruguay';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'QR code & document types', '[["QR code", "Required on printed/PDF representations, linking to DGI''s public CFE verification tool"], ["Main document types", "e-Factura (B2B), e-Ticket (B2C/retail), e-Factura de Exportación, e-Remito (waybill), e-Resguardo (withholding receipt), plus credit/debit notes for each"], ["Contingency", "CFC (Comprobante Fiscal Contingencia), used when the primary system or connectivity is unavailable"], ["Verification", "DGI''s own online tool lets any recipient check a CFE''s authenticity directly"]]', 'Confirm your invoicing software actually produces the specific CFE type your transaction requires -- issuing an e-Ticket where an e-Factura was needed, or vice versa, creates real compliance friction.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Uruguay';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Legal basis & schema version', '[["Founding decree", "Decreto 36/012 (8 February 2012)"], ["Operational framework", "Resolución DGI 798/012 (8 May 2012)"], ["Current schema version", "CFE format v25 / v25.1, per DGI''s published technical specification"], ["Penalty cross-reference", "Decreto 36/012, Art. 17 -- applies Uruguay''s general tax-documentation penalty regime, not a CFE-specific fine schedule"]]', NULL, NULL);
INSERT INTO deep_dive_lifecycle_cards (country_id, section, sort_order, display_style) SELECT id, 'scope_transmission', 0, 'pills' FROM countries WHERE name_en = 'Uruguay';
INSERT INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 'en', 'The CFE flow', 'A compliant invoice moves through this sequence under DGI''s CFE regime:', 'This is not a strict per-invoice clearance gate -- DGI pre-authorizes the numbering, not each individual document in real time -- but every CFE must still reach DGI and pass its checks to be a valid tax document.');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 0, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Issuer requests a numbered range (CAE) from DGI, valid two years');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 1, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Invoice generated as signed XML using an authorized number from that range');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 2, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'CFE transmitted to DGI, which performs structural/format validation');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 3, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'CFE delivered to the recipient, with a QR code for public verification');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 4, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Document remains subject to DGI''s later consistency and audit review');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Uruguay';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'What''s required by law', '[["Decreto 36/012 (2012)", "Founding decree creating the CFE regime"], ["Resolución 798/012 (2012)", "Technical/operational framework"], ["Phased rollout by revenue tier (2014-2019)", "Large taxpayers first, smaller taxpayers added in later annual waves"], ["Resolución 2548/023 (2023)", "Set the final 31 December 2024 deadline for the remaining taxpayer population"]]', 'This is the legal timeline -- see the next card for exactly who''s covered as of the January 2025 universal mandate.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Uruguay';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Who''s still exempt after the January 2025 universal mandate', '[["Small-scale agriculture", "Exclusively agricultural activity, annual income below UI 4,000,000"], ["Construction value-add", "VAT taxpayers performing only value-added construction services on real property"], ["IRNR taxpayers", "Non-resident income tax payers"], ["Fully VAT-exempt activity", "Except direct/indirect users of free trade zones, who remain in scope"], ["Simplified micro-enterprise regimes", "Monotributo, Monotributo Social MIDES, and Aporte Único participants"]]', 'This list reflects DGI''s own 28 November 2024 announcement -- if you''re not sure whether an exemption still applies to your business, confirm directly with DGI rather than assuming an older carve-out survived the January 2025 closure.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Uruguay';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚖️ Uruguay doesn''t set CFE-specific fines', NULL, NULL, 'Decreto 36/012, Art. 17 explicitly states that CFE non-compliance is punished under Uruguay''s general tax-documentation penalty regime, not a dedicated e-invoicing fine schedule. That regime lives in the Código Tributario (Ley 14.306, 1974) -- the provisions below are what actually governs exposure, not the round-number peso figures sometimes circulated by vendor content, which this page deliberately doesn''t repeat because they couldn''t be traced to a verifiable source.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Uruguay';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📋 Formal non-compliance and understated tax', NULL, NULL, 'Article 95 of the Código Tributario covers ''contravención'' -- violation of formal duties, including the duty to issue CFE correctly -- with a fine set in the code''s text; whether that figure has been administratively updated since the 1974 law was written couldn''t be independently confirmed, so treat any specific peso amount cited elsewhere with caution. Separately, Article 97 addresses ''omisión de pago'': where CFE irregularities lead to understated VAT or IRAE liability, the fine is one to five times the omitted tax amount.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Uruguay';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🔒 Practical consequences beyond a fine', NULL, NULL, 'A CFE that''s rejected or never properly issued is treated as if no invoice existed -- the recipient loses the ability to deduct the expense or claim the associated VAT credit. Multiple practitioner sources also tie serious or repeated non-compliance to the risk of DGI suspending a taxpayer''s Certificado Único, the general tax-compliance certificate required for government contracting, bank credit, and many commercial transactions -- though no single codified rule stating that CFE failure automatically triggers that suspension could be confirmed, so treat it as a real practical risk rather than an automatic legal consequence.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 3 FROM countries WHERE name_en = 'Uruguay';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🚨 Deceit-based fraud is a criminal offense', NULL, NULL, 'Article 110 of the Código Tributario makes ''defraudación tributaria'' -- using deceit to obtain an undue benefit at the state''s expense -- a criminal offense punishable by six months to six years'' imprisonment. Prosecution requires DGI itself to file a formal, reasoned complaint; this is reserved for genuine fraud, not routine formal non-compliance.');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Uruguay';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Formal non-compliance with CFE issuance duties (Código Tributario, Art. 95 -- ''contravención'')', 'A fine set under Art. 95''s general contravención schedule -- confirm the current applicable amount with DGI or a Uruguayan tax adviser rather than relying on an unverified figure', '—');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Uruguay';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Understated VAT/IRAE liability resulting from CFE irregularities (Código Tributario, Art. 97 -- ''omisión de pago'')', '1 to 5 times the omitted tax amount', '—');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Uruguay';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Deceit-based tax fraud (Código Tributario, Art. 110 -- ''defraudación tributaria'')', '6 months to 6 years'' imprisonment; requires a formal DGI complaint', '—');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Uruguay';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm whether your business is already required to issue CFE', 'Check whether you were captured by an earlier revenue-tier wave (2014-2019) or only came into scope with the January 2025 universal mandate -- and confirm you don''t fall into one of the narrow remaining exemptions.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Uruguay';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Register with DGI as an electronic issuer and obtain a valid certificate', 'You''ll need an accredited electronic certificate for signing CFE, and to request your first numbered range (CAE) from DGI before you can issue compliant documents.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Uruguay';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Choose the right CFE type for each transaction', 'Use e-Factura for B2B sales, e-Ticket for retail/B2C, and the corresponding export, waybill, or withholding document types where they apply -- issuing the wrong type creates real compliance friction.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Uruguay';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Build XML generation, digital signing, and DGI transmission into your invoicing system', 'Confirm your software actually produces a compliant, signed CFE XML and transmits it to DGI -- don''t rely on a manual or batch process that could fall behind DGI''s numbering and validation requirements.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Uruguay';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Track your CAE range and request a new one before it runs out', 'A CAE range is valid for two years and must be requested in batches of at least 100 numbers -- running out mid-operation would stop you from issuing compliant invoices.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 5 FROM countries WHERE name_en = 'Uruguay';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your software or provider is certified against the current CFE schema version', 'DGI periodically revises the CFE technical specification -- most recently to v25.1, with new mandatory controls from 15 April 2026 -- so ask your provider directly rather than assuming ongoing compatibility.');
INSERT INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://www.efactura.dgi.gub.uy/', 0 FROM countries WHERE name_en = 'Uruguay';
INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'DGI e-Factura — the official CFE portal, technical specifications, and public invoice verification tool');
INSERT INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://www.gub.uy/direccion-general-impositiva/tematica/factura-electronica', 1 FROM countries WHERE name_en = 'Uruguay';
INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'Dirección General Impositiva (DGI) — institutional page on Facturación Electrónica, official announcements and resolutions');
